-- Orion fictional legacy baseline. Restore only to an empty personal lab database.

-- No credentials, evaluation answers, security fixtures or original application source.

SET NAMES utf8mb4;

SET time_zone = '+00:00';

CREATE TABLE `plans` (
  `plan_id` VARCHAR(64),
  `name` VARCHAR(512),
  `monthly_seat_usd` DECIMAL(12,4),
  PRIMARY KEY (`plan_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `agents` (
  `agent_id` VARCHAR(64),
  `name` VARCHAR(512),
  `team` VARCHAR(512),
  `shift` VARCHAR(512),
  `skills` VARCHAR(512),
  PRIMARY KEY (`agent_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `customers` (
  `customer_id` VARCHAR(64),
  `company` VARCHAR(512),
  `industry` VARCHAR(512),
  `country` VARCHAR(512),
  `region` VARCHAR(512),
  `company_size` VARCHAR(512),
  `plan_id` VARCHAR(512),
  `seats` INTEGER,
  `signup_date` DATE,
  `contact_email` VARCHAR(512),
  `acquisition_source` VARCHAR(512),
  PRIMARY KEY (`customer_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;




CREATE TABLE `subscriptions` (
  `subscription_id` VARCHAR(64),
  `customer_id` VARCHAR(512),
  `plan_id` VARCHAR(512),
  `seats` INTEGER,
  `started_at` DATE,
  `status` VARCHAR(512),
  PRIMARY KEY (`subscription_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;




CREATE TABLE `tickets` (
  `ticket_id` VARCHAR(64),
  `customer_id` VARCHAR(512),
  `agent_id` VARCHAR(512),
  `created_at` DATETIME(6),
  `first_response_at` DATETIME(6),
  `resolved_at` DATETIME(6),
  `category` VARCHAR(512),
  `priority` VARCHAR(512),
  `status` VARCHAR(512),
  `channel` VARCHAR(512),
  `component` VARCHAR(512),
  `subject` VARCHAR(512),
  `body` TEXT,
  `sla_response_hours` DECIMAL(12,4),
  `sla_resolution_hours` DECIMAL(12,4),
  `first_response_hours` DECIMAL(12,4),
  `resolution_hours` DECIMAL(12,4),
  `csat` INTEGER,
  `reopened_count` INTEGER,
  `escalated` BOOLEAN,
  `sentiment` VARCHAR(512),
  `plan_id` VARCHAR(512),
  `industry` VARCHAR(512),
  `region` VARCHAR(512),
  `company_size` VARCHAR(512),
  PRIMARY KEY (`ticket_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;









































CREATE TABLE `messages` (
  `message_id` VARCHAR(64),
  `ticket_id` VARCHAR(512),
  `created_at` DATETIME(6),
  `author_role` VARCHAR(512),
  `body` TEXT,
  PRIMARY KEY (`message_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
















































































































































































































































































































































































CREATE TABLE `invoices` (
  `invoice_id` VARCHAR(64),
  `customer_id` VARCHAR(512),
  `month` VARCHAR(512),
  `plan_id` VARCHAR(512),
  `seats` INTEGER,
  `unit_price_usd` DECIMAL(12,4),
  `total_usd` DECIMAL(12,4),
  `status` VARCHAR(512),
  PRIMARY KEY (`invoice_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;



















CREATE TABLE `ticket_events` (
  `ticket_id` VARCHAR(64),
  `event_at` DATETIME(6),
  `event_type` VARCHAR(64),
  PRIMARY KEY (`ticket_id`,`event_at`,`event_type`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;













































































CREATE TABLE `releases` (
  `release_id` VARCHAR(64),
  `date` DATE,
  `version` VARCHAR(512),
  `change` TEXT,
  PRIMARY KEY (`release_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `incidents` (
  `incident_id` VARCHAR(64),
  `start` DATETIME(6),
  `end` DATETIME(6),
  `service` VARCHAR(512),
  `description` TEXT,
  PRIMARY KEY (`incident_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `sla_policy` (
  `priority` VARCHAR(64),
  `plan_id` VARCHAR(64),
  `response_hours` DECIMAL(12,4),
  `resolution_hours` DECIMAL(12,4),
  `time_basis` VARCHAR(512),
  PRIMARY KEY (`priority`,`plan_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `knowledge_articles` (
  `article_id` VARCHAR(64),
  `title` VARCHAR(512),
  `category` VARCHAR(512),
  `body` TEXT,
  PRIMARY KEY (`article_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `company_documents` (
  `document_id` VARCHAR(64),
  `title` VARCHAR(512),
  `owner` VARCHAR(512),
  `body` TEXT,
  PRIMARY KEY (`document_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `staff_requests` (
  `request_id` VARCHAR(64),
  `title` VARCHAR(512),
  `requester` VARCHAR(512),
  `body` TEXT,
  PRIMARY KEY (`request_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE TABLE `lab_metadata` (
  `baseline_id` VARCHAR(64),
  `snapshot_utc` VARCHAR(512),
  `fictional` BOOLEAN,
  `scenario` VARCHAR(512),
  PRIMARY KEY (`baseline_id`)
) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;


CREATE INDEX `tickets_customer_id_idx` ON `tickets` (`customer_id`);

CREATE INDEX `tickets_created_at_idx` ON `tickets` (`created_at`);

CREATE INDEX `tickets_status_idx` ON `tickets` (`status`);

CREATE INDEX `messages_ticket_id_idx` ON `messages` (`ticket_id`);

-- Logical foreign-key relationships are validated by the packaging tool; this baseline does not claim database-enforced foreign keys.
